import{_ as o,o as t,c as a,a4 as r}from"./chunks/framework.DPwo9VAo.js";const m=JSON.parse('{"title":"Peers and bundle size","description":"","frontmatter":{},"headers":[],"relativePath":"core/peers-and-bundle.md","filePath":"core/peers-and-bundle.md","lastUpdated":1788969992000}'),d={name:"core/peers-and-bundle.md"};function s(l,e,n,c,i,p){return t(),a("div",null,e[0]||(e[0]=[r('<h1 id="peers-and-bundle-size" tabindex="-1">Peers and bundle size <a class="header-anchor" href="#peers-and-bundle-size" aria-label="Permalink to &quot;Peers and bundle size&quot;">​</a></h1><p>Brief guide to what you need on the client vs optional GIS format peers.</p><p>Related: <a href="./minimal-starter.html">Minimal starter</a> · <a href="./stable-api.html">Stable API</a> · <a href="./../dataset/module/CreateControl.html">CreateControl</a></p><h2 id="lite-recipe-browser-shell-only" tabindex="-1">Lite recipe (browser shell only) <a class="header-anchor" href="#lite-recipe-browser-shell-only" aria-label="Permalink to &quot;Lite recipe (browser shell only)&quot;">​</a></h2><p>Smallest useful client bundle for <strong>inline GeoJSON / in-memory layers</strong>:</p><ol><li>Peers: <code>maplibre-gl</code> (+ Vue or React).</li><li>Packages: <code>@hungpvq/map-core</code> + <code>@hungpvq/vue-map-core</code> <strong>or</strong> <code>@hungpvq/react-map-core</code>.</li><li>Optional dataset list UI: <code>@hungpvq/map-dataset</code> + matching adapter + <code>installMapApp</code> / <code>createMapAppPlugin</code>.</li><li>Import CSS once (<code>*/style.css</code>). Follow <a href="./minimal-starter.html">Minimal starter</a>.</li></ol><p><strong>Do not install</strong> for lite: <code>@hungpvq/map-draw</code>, CreateControl GIS peers (<code>shpjs</code>, <code>papaparse</code>, togeojson, jszip, topojson-client), or the GIS Vite worker plugin.</p><p>There is no separate npm “lite” package — use the root/<code>./style.css</code> entries and skip optional peers/subpaths.</p><h2 id="minimal-map-shell" tabindex="-1">Minimal map shell <a class="header-anchor" href="#minimal-map-shell" aria-label="Permalink to &quot;Minimal map shell&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Role</th></tr></thead><tbody><tr><td><code>maplibre-gl</code></td><td>Map engine (peer)</td></tr><tr><td><code>@hungpvq/map-core</code></td><td>Store, registry, theme, a11y helpers</td></tr><tr><td><code>@hungpvq/vue-map-core</code> or <code>@hungpvq/react-map-core</code></td><td><code>Map</code> shell + controls</td></tr><tr><td><code>@hungpvq/map-dataset</code> + vue/react adapter</td><td>Datasets + LayerControl (optional for bare canvas)</td></tr></tbody></table><p>Bootstrap adapters with <code>installMapApp</code> / <code>createMapAppPlugin</code> (Vue) so theme + dataset registry install once. CSS still imported by the app.</p><p><strong>Not required</strong> for inline GeoJSON / in-memory FeatureCollection: GIS worker Vite plugin, <code>shpjs</code>, CSV/KML parsers.</p><h2 id="full-gis-createcontrol" tabindex="-1">Full GIS / CreateControl <a class="header-anchor" href="#full-gis-createcontrol" aria-label="Permalink to &quot;Full GIS / CreateControl&quot;">​</a></h2><p>When using CreateControl file upload / <code>loadGis*</code> / worker parse, install optional peers as needed:</p><table tabindex="0"><thead><tr><th>Peer</th><th>Formats</th></tr></thead><tbody><tr><td><code>shpjs</code></td><td>Shapefile</td></tr><tr><td><code>papaparse</code></td><td>CSV</td></tr><tr><td><code>@tmcw/togeojson</code> + <code>@xmldom/xmldom</code></td><td>KML / GPX</td></tr><tr><td><code>jszip</code></td><td>KMZ / zipped shapefile</td></tr><tr><td><code>topojson-client</code></td><td>TopoJSON</td></tr></tbody></table><p>Wire the worker with <code>@hungpvq/map-dataset/vite</code> → <code>mapDatasetGisWorker()</code> when parsing off the main thread. Soft client size limit: <code>CREATE_CONTROL_MAX_FILE_BYTES</code> / <code>assertCreateControlFileSize</code> on <code>@hungpvq/map-dataset/create-control</code>. CreateControl remembers last name/type/CRS in <code>sessionStorage</code> (<code>load/saveCreateControlDraft</code>).</p><h2 id="theme" tabindex="-1">Theme <a class="header-anchor" href="#theme" aria-label="Permalink to &quot;Theme&quot;">​</a></h2><p><code>bootstrapMapTheme(&#39;auto&#39;)</code> follows <code>prefers-color-scheme</code> (light/dark). ThemeControl also listens to the media query when mode is <code>auto</code>.</p><h2 id="keyboard-a11y-map-core" tabindex="-1">Keyboard / a11y (map-core) <a class="header-anchor" href="#keyboard-a11y-map-core" aria-label="Permalink to &quot;Keyboard / a11y (map-core)&quot;">​</a></h2><p><code>bindMapKeyboardShortcuts({ mapId })</code> (on by default in <code>Map</code>): <strong>Esc</strong> closes the top open panel; <strong><code>/</code></strong> focuses LayerControl search (<code>data-map-layer-search</code>). Opt out with <code>keyboardShortcuts={false}</code> / <code>:keyboard-shortcuts=&quot;false&quot;</code>.</p><h2 id="fitbounds-overlays" tabindex="-1">fitBounds overlays <a class="header-anchor" href="#fitbounds-overlays" aria-label="Permalink to &quot;fitBounds overlays&quot;">​</a></h2><p><code>fitBounds</code> pads for open sidebars, floats, popups, and bottom sheets so fitted data stays in the visible map area. Pass <code>mapId</code> / <code>controlIds</code> for registry hints, or <code>ignoreOverlays: true</code> for flat padding.</p>',22)]))}const u=o(d,[["render",s]]);export{m as __pageData,u as default};
